var nonCyrillic = regexp.MustCompile(`[^а-яёА-ЯЁ]+`)
var cyrillicWord = regexp.MustCompile(`\p{Cyrillic}+`)

func OnlyCyrillic(s string) string {
	return nonCyrillic.ReplaceAllString(s, "")
}

func main() {
	fmt.Println(OnlyCyrillic("Hello, Мир! 123 ёлка"))                  // Мирёлка
	fmt.Println(cyrillicWord.FindAllString("Hello, Мир! 123 ёлка", -1)) // [Мир ёлка]
}
```

Notes:
